INSERT INTO destinations (id,name,province,region_group,lat,lng,type,budget_php,days,activities,popular,best_start,best_end,description,getting_there,tip,region_code,region_name,tiktok,hidden) VALUES
(1,'Baguio','Benguet','L',16.402,120.596,'City',6000,3,'ss,fd,cw,ph',1,11,5,'Cool pine-covered "Summer Capital" with markets, cafés, and Burnham Park.','Bus from Manila, about 6 hrs, or fly to Clark and drive.','Weekends and holidays are packed, so go midweek.','CAR','CAR · Cordillera Administrative Region',1,0),
(2,'Sagada','Mountain Province','L',17.084,120.901,'Mountain',6200,3,'hk,cv,cm',1,11,4,'Mountain town known for hanging coffins, limestone caves, and sea-of-clouds sunrises.','Overnight bus from Manila to Bontoc or Sagada, about 12 hrs.','Cave tours need a local guide, and mornings are cold.','CAR','CAR · Cordillera Administrative Region',1,0),
(3,'Banaue Rice Terraces','Ifugao','L',16.927,121.057,'Heritage',6500,3,'hk,cw,ph',1,11,5,'UNESCO-listed terraces carved into the Ifugao mountains over centuries.','Overnight bus from Manila, about 9 to 10 hrs.','Visit viewpoints early for clearer skies and fewer tour groups.','CAR','CAR · Cordillera Administrative Region',1,0),
(4,'Batad Rice Terraces','Ifugao','L',16.914,121.097,'Heritage',6000,3,'hk,cw,ph',0,11,5,'Amphitheater-shaped terraces reached by a short trek from the road.','From Banaue by jeepney or tricycle to the saddle, then hike 30 to 45 min.','Wear shoes with good grip, since steps get slippery when wet.','CAR','CAR · Cordillera Administrative Region',1,0),
(5,'Kiangan','Ifugao','L',16.783,121.096,'Heritage',5500,2,'cw,hk',0,11,5,'Ifugao town with a war memorial and quieter rice-terrace walks.','From Banaue or Lagawe by jeepney, about 1 hr.','Hire a local guide for village treks.','CAR','CAR · Cordillera Administrative Region',0,0),
(6,'Buscalan','Kalinga','L',17.383,121.150,'Heritage',6000,3,'cw,hk,ph',0,11,4,'Kalinga village where traditional hand-tapped tattooing is practiced.','Bus to Tabuk or Bontoc, then a ride and short trek to the village.','Be respectful, and arrange tattoo sessions with the artists directly.','CAR','CAR · Cordillera Administrative Region',1,0),
(7,'Vigan','Ilocos Sur','L',17.575,120.387,'Heritage',5500,2,'cw,fd,ss,bk',1,11,5,'Preserved Spanish-colonial town with cobblestone Calle Crisologo and horse-drawn calesas.','Bus from Manila, about 8 to 9 hrs, or fly to Laoag and ride south.','Try Vigan empanada and longganisa, and stroll the streets at night.','R1','Region I · Ilocos Region',1,0),
(8,'Paoay Church & Dunes','Ilocos Norte','L',18.059,120.520,'Heritage',4500,2,'cw,ss,ad',1,11,5,'Baroque UNESCO church and the La Paz sand dunes nearby.','Near Laoag. Tricycle or van from Laoag City, about 30 min.','Book 4x4 and sandboarding on arrival, and go late afternoon.','R1','Region I · Ilocos Region',1,0),
(9,'Pagudpud','Ilocos Norte','L',18.558,120.790,'Beach',5800,3,'sw,sf,ss',1,3,6,'Northern beach town with white sand at Saud and the Blue Lagoon.','Bus from Manila about 12 hrs, or fly to Laoag and drive 2 hrs.','Surf is rough in the rainy months, so check conditions first.','R1','Region I · Ilocos Region',1,0),
(10,'Bangui Windmills','Ilocos Norte','L',18.534,120.759,'Nature',4500,2,'ph,bk,ss',1,11,5,'Row of wind turbines along a curving beach, popular for photos.','From Pagudpud by tricycle or van, about 20 to 30 min.','Golden hour gives the best photos.','R1','Region I · Ilocos Region',1,0),
(11,'Kapurpurawan Rock','Ilocos Norte','L',18.526,120.624,'Nature',4500,2,'ph,ss',0,11,5,'White limestone formations on the Burgos coast.','From Laoag by van or bus to Burgos, about 1 hr.','A short walk or horse ride from the parking area, so wear sun protection.','R1','Region I · Ilocos Region',1,0),
(12,'Mt. Pulag','Benguet','L',16.597,120.892,'Mountain',5500,2,'hk,cm,ph',1,12,2,'One of Luzon''s highest peaks, known for sea-of-clouds sunrise camps.','Overnight bus to Baguio, then jeepney to the Ranger Station.','Permit and orientation are required, and it can get near freezing.','CAR','CAR · Cordillera Administrative Region',1,0),
(13,'Mt. Batulao','Batangas','L',14.050,120.800,'Mountain',2000,1,'hk,cm,ph',1,11,4,'Popular beginner-to-intermediate day hike with grassy ridges.','Bus from Manila to Nasugbu, about 2 to 3 hrs, then get off near the trailhead.','Start early to avoid the heat, since the ridge has little shade.','R4A','Region IV-A · CALABARZON',1,0),
(14,'Mt. Pico de Loro','Cavite','L',14.235,120.620,'Mountain',2500,1,'hk,cm',0,11,4,'Distinct monolith summit on the Cavite and Batangas border.','From Manila by bus, then tricycle to Ternate or Maragondon.','Climbing the monolith needs a guide and dry conditions.','R4A','Region IV-A · CALABARZON',1,0),
(15,'Hundred Islands','Pangasinan','L',16.200,120.033,'Island',3500,2,'ih,sw,kc',1,11,5,'Over a hundred limestone islets for island hopping and kayaking.','Bus from Manila to Alaminos, about 5 to 6 hrs, then tricycle to the park.','Book a boat package at the tourism office, and expect crowds on weekends.','R1','Region I · Ilocos Region',1,0),
(16,'Bolinao','Pangasinan','L',16.390,119.890,'Beach',3500,2,'sw,ss,cv',0,3,6,'Quiet northwest town with beaches, caves, and Patar Beach.','Bus from Manila to Bolinao, about 7 hrs.','Easy to combine with Hundred Islands in one trip.','R1','Region I · Ilocos Region',1,0),
(17,'San Juan, La Union','La Union','L',16.670,120.330,'Surf',4000,2,'sf,fd,rl',1,11,4,'Surf town with beginner waves, cafés, and a lively beach scene.','Bus from Manila to San Fernando, about 5 to 6 hrs, then tricycle.','Surf schools offer lessons, and waves are best in the dry months.','R1','Region I · Ilocos Region',1,0),
(18,'Anawangin Cove','Zambales','L',15.000,120.078,'Beach',3800,2,'cm,sw,hk',0,11,5,'Pine-lined cove in Zambales popular for camping.','Bus to San Antonio, then a boat from Pundaquit, about 45 min.','Bring all supplies and carry out your trash.','R3','Region III · Central Luzon',1,0),
(19,'Nagsasa Cove','Zambales','L',14.930,120.030,'Beach',3800,2,'cm,sw,hk',0,11,5,'Calmer cove next to Anawangin with a long gray-sand beach.','Boat from Pundaquit, about 1 hr.','Facilities are basic, so plan water and food ahead.','R3','Region III · Central Luzon',1,0),
(20,'Potipot Island','Zambales','L',15.667,119.917,'Island',3500,2,'sw,ih',0,3,6,'Small white-sand island off Candelaria, Zambales.','Bus to Candelaria, then a short boat ride.','Good for a quick getaway, but crowded on weekends.','R3','Region III · Central Luzon',0,0),
(21,'Subic Bay','Zambales','L',14.821,120.286,'Adventure',4000,2,'ad,wl,ss',0,11,5,'Former naval base with a jungle zoo, dive spots, and beaches.','Bus from Manila to Subic, about 3 hrs.','Combine a nature outing with a wreck dive.','R3','Region III · Central Luzon',0,0),
(22,'Mt. Pinatubo Crater','Tarlac','L',15.145,120.350,'Lake',4500,2,'hk,ss,ph',1,11,4,'Crater lake reached by a 4x4 ride and a short trek.','Travel to Capas, Tarlac, then 4x4 to the trailhead.','Book a guided tour and wear sun protection on the exposed trail.','R3','Region III · Central Luzon',1,0),
(23,'Bagac','Bataan','L',14.594,120.397,'Heritage',4500,2,'cw,ss',0,11,5,'Coastal Bataan town near heritage houses and quiet beaches.','Bus from Manila to Bagac, about 3 hrs.','Pair it with a visit to the heritage village nearby.','R3','Region III · Central Luzon',0,0),
(24,'Clark Freeport','Pampanga','L',15.180,120.560,'City',4000,2,'fd,ss,ad',0,11,5,'Former air base with food, malls, a zoo, and adventure parks.','Fly directly to Clark International Airport.','A handy gateway for Northern Luzon trips.','R3','Region III · Central Luzon',0,0),
(25,'Ditumabo Falls','Aurora','L',15.660,121.600,'Waterfall',3500,1,'sw,hk',0,6,11,'Wide waterfall in Aurora, also called Mother Falls.','Drive from Baler to San Luis, then a short trek.','Water volume is higher in the wetter months.','R3','Region III · Central Luzon',1,0),
(26,'Baler','Aurora','L',15.759,121.563,'Surf',5500,3,'sf,sw,ss',1,10,2,'Birthplace of Philippine surfing, with long beaches and mellow breaks.','Bus from Manila, about 6 hrs, or van from Cabanatuan.','Surf season is roughly October to February.','R3','Region III · Central Luzon',1,0),
(27,'Callao Cave','Cagayan','L',17.672,121.825,'Cave',4500,3,'cv,kc',0,11,5,'Large limestone cave with chambers and a natural skylight.','Fly to Tuguegarao, then drive to Peñablanca, about 45 min.','Combine with river boat rides nearby.','R2','Region II · Cagayan Valley',1,0),
(28,'Anguib Beach','Cagayan','L',18.478,122.220,'Beach',6500,3,'sw,cm',0,3,6,'Remote white-sand beach in Santa Ana, Cagayan.','Fly to Tuguegarao, drive to Santa Ana, then take a boat.','Bring cash and supplies, since services are limited.','R2','Region II · Cagayan Valley',0,0),
(29,'Palaui Island','Cagayan','L',18.500,122.150,'Island',6000,3,'hk,sw,ih',0,3,6,'Protected island with Cape Engaño Lighthouse and quiet beaches.','Drive to Santa Ana, then a short boat to Palaui.','Hike to the lighthouse in the cooler hours.','R2','Region II · Cagayan Valley',1,0),
(30,'Sabtang','Batanes','L',20.330,121.883,'Heritage',14000,5,'cw,ss,hk,ph',0,3,6,'Island with traditional stone houses and rugged coastline.','Fly to Basco, then boat from Ivana to Sabtang, about 45 min.','Weather affects boats, so keep your schedule flexible.','R2','Region II · Cagayan Valley',1,0),
(31,'Batan Island','Batanes','L',20.449,121.970,'Island',15000,5,'ss,hk,cw,ph',1,3,6,'Rolling green hills, stone houses, and windswept coasts.','Fly from Manila to Basco, about 1.5 hrs.','Flights depend on weather, so allow buffer days.','R2','Region II · Cagayan Valley',1,0),
(32,'Tanay','Rizal','L',14.498,121.355,'Waterfall',2500,1,'sw,hk',1,6,11,'Rizal town with falls, caves, and cool viewpoints.','Bus or van from Manila to Tanay, about 2 hrs.','Arrive early on weekends to beat the crowds.','R4A','Region IV-A · CALABARZON',0,0),
(33,'Pagsanjan Falls','Laguna','L',14.277,121.454,'Waterfall',3000,1,'kc,sw,ad',1,6,11,'Boat ride through a gorge to a waterfall, with local boatmen.','Bus from Manila to Pagsanjan, about 2 hrs.','Agree on the fee before riding, since it includes the paddlers.','R4A','Region IV-A · CALABARZON',1,0),
(301,'San Bartolome Church Nagcarlan','Laguna','L',14.1330,121.4150,'Heritage',2000,1,'cw,ss,ph',0,11,5,'18th-century church in Nagcarlan town center.','Bus to Santa Cruz, then a jeepney.','Visit in the morning.','R4A','Region IV-A · CALABARZON',0,0),
(35,'Lucban & Tayabas','Quezon','L',14.113,121.556,'Heritage',3000,1,'cw,fd,ss',0,11,5,'Quezon towns known for the Pahiyas festival, longganisa, and heritage churches.','Bus from Manila to Lucena, then jeepney, about 3 hrs.','Visit in May to see the Pahiyas decorations.','R4A','Region IV-A · CALABARZON',1,0),
(36,'Borawan Island','Quezon','L',14.667,121.617,'Island',3500,2,'sw,kc',0,3,6,'Small island near Real, Quezon, with white sand and calm water.','Bus to Real, then a short boat ride.','Weekdays are quieter.','R4A','Region IV-A · CALABARZON',0,0),
(37,'Taal Heritage Town','Batangas','L',13.883,120.930,'Heritage',3000,1,'cw,ss,fd',0,11,5,'Batangas town of old houses and a grand basilica.','Bus from Manila to Taal, about 2.5 hrs.','Try the local embroidery and barako coffee.','R4A','Region IV-A · CALABARZON',1,0),
(38,'Tagaytay & Taal','Batangas','L',14.115,120.962,'Mountain',3500,2,'ss,hk,fd',1,11,5,'Ridge-top town with views of Taal Volcano and Taal Lake.','Bus or van from Manila, about 1.5 to 2 hrs.','Weekends are busy, so go early for clear views.','R4A','Region IV-A · CALABARZON',1,0),
(39,'Calatagan','Batangas','L',13.833,120.633,'Beach',4500,2,'sw,dv',0,3,6,'Batangas coastal town with beach resorts and diving.','Drive or bus from Manila to Calatagan, about 3 hrs.','Check sea conditions before booking dives.','R4A','Region IV-A · CALABARZON',1,0),
(40,'Anilao','Batangas','L',13.760,120.910,'Diving',6000,2,'dv,sn',1,11,5,'Batangas diving hub known for macro marine life.','Bus to Mabini, about 3 hrs, then a boat to dive sites.','Dive sites are best on calm mornings.','R4A','Region IV-A · CALABARZON',1,0),
(41,'Verde Island','Batangas','L',13.530,121.080,'Island',4000,2,'dv,sn',0,11,5,'Verde Island Passage island with rich marine life.','Boat from Batangas City, about 1 hr.','Stay at a small resort for the best access.','R4A','Region IV-A · CALABARZON',1,0),
(42,'Puerto Galera','Oriental Mindoro','L',13.500,120.950,'Beach',6500,3,'dv,sn,sw',1,11,5,'Mindoro beach town with Sabang diving and White Beach.','Bus to Batangas Pier, then a ferry to Puerto Galera.','Dive centers run day trips, so book ahead on weekends.','R4B','MIMAROPA · Region IV-B',1,0),
(43,'Apo Reef','Occidental Mindoro','L',12.667,120.467,'Diving',9000,3,'dv,sn,wl',0,3,6,'Large reef system with diving and snorkeling off Sablayan.','Travel to Sablayan, then take a day trip or liveaboard.','Trips depend on weather, so keep your dates flexible.','R4B','MIMAROPA · Region IV-B',0,0),
(44,'Pandan Island','Occidental Mindoro','L',12.840,120.750,'Island',6000,2,'sn,dv',0,3,6,'Small resort island for snorkeling off Sablayan.','From Sablayan by boat, about 15 min.','Great for a quiet, nature-focused stay.','R4B','MIMAROPA · Region IV-B',1,0),
(45,'Marinduque','Marinduque','L',13.447,121.842,'Island',5000,3,'cw,sw,ss',0,3,5,'Heart-shaped island known for the Moriones Festival at Easter.','Ferry from Lucena to Balanacan, about 3 hrs, or fly from Manila.','Plan ahead if visiting during Holy Week.','R4B','MIMAROPA · Region IV-B',0,0),
(46,'Romblon Island','Romblon','L',12.580,122.270,'Island',5000,3,'sw,ph,ss',0,3,6,'Marble-producing island with calm beaches and old forts.','Fly or ferry to Romblon via Batangas or Roxas.','Schedules are limited, so confirm transfers early.','R4B','MIMAROPA · Region IV-B',0,0),
(47,'Sibuyan Island','Romblon','L',12.430,122.600,'Nature',6000,3,'hk,kc,cm',0,11,5,'Mountain island sometimes called the Galapagos of Asia.','Ferry from Batangas via Romblon, or fly to Tablas and cross over.','Travel takes time, so plan 2 to 3 nights.','R4B','MIMAROPA · Region IV-B',0,0),
(48,'Calaguas Islands','Camarines Norte','L',14.033,122.933,'Beach',6500,3,'sw,cm',0,3,6,'Powdery white beaches and calm blue water in Camarines Norte.','Bus to Vinzons or Paracale, then a boat to Mahabang Buhangin.','Bring your own supplies, since amenities are basic.','R5','Region V · Bicol Region',1,0),
(49,'Caramoan','Camarines Sur','L',13.770,123.860,'Island',7500,3,'ih,sn,kc',1,3,6,'Limestone islets and lagoons used for island hopping.','Bus to Naga, then van and boat from Sabang Port.','Boat transfers depend on sea conditions.','R5','Region V · Bicol Region',1,0),
(50,'CamSur Watersports','Camarines Sur','L',13.580,123.280,'Adventure',4000,2,'ad',1,11,5,'Wakeboarding park with cable systems for all levels.','Fly to Naga and take a van, or drive from Manila.','Beginners can book lessons.','R5','Region V · Bicol Region',1,0),
(51,'Puraran Beach','Catanduanes','L',13.630,124.430,'Surf',6000,3,'sf,sw',0,8,10,'Catanduanes surf spot with strong waves and scenic coast.','Fly to Virac, then drive about 1 to 2 hrs.','Surf is challenging, so it suits experienced riders.','R5','Region V · Bicol Region',1,0),
(52,'Mayon Volcano','Albay','L',13.257,123.686,'Mountain',5000,2,'ss,hk,ph',1,11,5,'Near-perfect cone volcano with viewpoints and ATV tours.','Fly to Legazpi, then drive to viewpoints.','Clouds hide the summit by midday, so go early.','R5','Region V · Bicol Region',1,0),
(53,'Cagsawa Ruins','Albay','L',13.160,123.700,'Heritage',3000,1,'ss,cw,ph',1,11,5,'Remains of a church with a classic view of Mayon.','From Legazpi by tricycle or jeepney, about 20 min.','Visit early morning or late afternoon for photos.','R5','Region V · Bicol Region',1,0),
(54,'Donsol','Sorsogon','L',12.910,123.590,'Nature',6000,2,'wl,sn',1,11,6,'Whale shark interaction area off Sorsogon.','Bus to Donsol, or fly to Legazpi and drive about 1 hr.','Whale shark season runs about November to June.','R5','Region V · Bicol Region',1,0),
(55,'Bulusan Lake','Sorsogon','L',12.770,124.050,'Lake',3500,2,'kc,hk',0,3,6,'Crater lake in Sorsogon with calm paddling and walking trails.','From Sorsogon City by jeepney or van, about 1 hr.','Go in the morning for calmer water.','R5','Region V · Bicol Region',0,0),
(56,'Intramuros','Manila','L',14.589,120.975,'City',3000,1,'cw,ss,fd,bk',1,11,5,'Walled Spanish-era city with forts, churches, and museums.','Manila LRT, taxi, or ride-hailing to Intramuros.','Walk or bike with a guide for the best overview.','NCR','NCR · National Capital Region',1,0),
(57,'Binondo','Manila','L',14.601,120.974,'City',2500,1,'fd,cw',1,11,5,'Oldest Chinatown with food stalls, temples, and old shops.','Manila LRT-1 to Carriedo, then walk.','Come hungry, and try a food walk for dumplings and hopia.','NCR','NCR · National Capital Region',1,0),
(58,'El Nido','Palawan','L',11.178,119.392,'Island',7500,3,'ih,sn,kc',1,11,5,'Limestone cliffs, lagoons, and island-hopping tours in Palawan.','Fly to El Nido or Puerto Princesa, then van about 5 to 6 hrs.','Tours A to D cover different lagoons, so book early in peak months.','R4B','MIMAROPA · Region IV-B',1,0),
(59,'Nacpan Beach','Palawan','L',11.290,119.410,'Beach',6500,3,'sw,rl,ph',0,11,5,'Long white-sand beach near El Nido with a relaxed vibe.','From El Nido by tricycle, about 45 min.','Bring cash, since amenities are limited.','R4B','MIMAROPA · Region IV-B',1,0),
(60,'Coron','Palawan','L',11.999,120.204,'Diving',9800,4,'dv,sn,sw',1,11,5,'Shipwreck diving and island hopping in northern Palawan.','Fly to Busuanga, then van about 40 min.','Wreck dives are for certified divers, so check requirements.','R4B','MIMAROPA · Region IV-B',1,0),
(61,'Kayangan Lake','Palawan','L',11.985,120.235,'Lake',9000,3,'sw,ph,ss',1,11,5,'Clear lake in Coron with limestone views and snorkeling.','Part of Coron island-hopping tours by boat.','Go early, and expect entrance fees.','R4B','MIMAROPA · Region IV-B',1,0),
(62,'Culion','Palawan','L',11.850,120.020,'Heritage',6000,3,'cw,ss',0,11,5,'Historic island in Palawan with a former leprosarium.','Boat or flight from Coron or Busuanga.','Learn the island''s history at the museum.','R4B','MIMAROPA · Region IV-B',0,0),
(63,'Puerto Princesa','Palawan','L',9.739,118.735,'City',4500,2,'fd,cw,ss',1,11,5,'Palawan''s capital with Baywalk, markets, and tours.','Fly directly to Puerto Princesa International Airport.','A base for the Underground River and Honda Bay.','R4B','MIMAROPA · Region IV-B',1,0),
(64,'Honda Bay','Palawan','L',9.800,118.800,'Island',4000,1,'ih,sw,sn',1,11,5,'Island-hopping bay with sandbars and snorkeling near Puerto Princesa.','From Sta. Lourdes Wharf by boat.','Bring reef-safe sunscreen.','R4B','MIMAROPA · Region IV-B',1,0),
(65,'Underground River','Palawan','L',10.167,118.917,'Cave',7000,3,'kc,cv,wl',1,11,5,'UNESCO-listed subterranean river with cave formations.','Van from Puerto Princesa to Sabang, then a boat.','Permits sell out, so book ahead in peak season.','R4B','MIMAROPA · Region IV-B',1,0),
(66,'Port Barton','Palawan','L',10.415,119.175,'Beach',5500,3,'sn,ih,sw',0,11,5,'Laid-back bay with calm water and snorkeling spots.','Van from Puerto Princesa or El Nido, about 3 to 4 hrs.','Power can be limited, so bring cash.','R4B','MIMAROPA · Region IV-B',1,0),
(67,'Balabac','Palawan','L',7.980,117.050,'Island',12000,5,'ih,sw,sn,wl',0,3,6,'Southern Palawan archipelago with remote islands and sandbars.','Fly or van to Rizal, then boat to Balabac.','It''s remote, so arrange transport and supplies ahead.','R4B','MIMAROPA · Region IV-B',0,0),
(68,'Tubbataha Reefs','Palawan','L',8.850,119.900,'Diving',25000,5,'dv,wl',0,3,6,'UNESCO reef known for liveaboard diving.','Join a liveaboard from Puerto Princesa during the season.','Dive season is about March to June, so book far ahead.','R4B','MIMAROPA · Region IV-B',0,0),
(69,'Boracay','Aklan','V',11.967,121.925,'Beach',9000,4,'sw,sn,ss,rl',1,11,5,'Famous White Beach with sunsets, water sports, and nightlife.','Fly to Caticlan or Kalibo, then a boat from the Caticlan jetty.','Wind direction changes by season, and Bulabog Beach on the east is used for kitesurfing.','R6','Region VI · Western Visayas',1,0),
(70,'Kalibo','Aklan','V',11.700,122.367,'City',4000,2,'cw,fd',0,1,1,'Aklan capital and gateway to Boracay, known for the Ati-Atihan festival in January.','Fly to Kalibo International Airport.','Book lodging early if visiting during Ati-Atihan.','R6','Region VI · Western Visayas',0,0),
(71,'Malalison Island','Antique','V',11.617,122.050,'Island',5000,2,'sw,sn,hk',0,3,6,'Antique island with white-sand beaches and a hill viewpoint.','Boat from Culasi, Antique, about 30 min.','Bring cash and supplies, since facilities are simple.','R6','Region VI · Western Visayas',0,0),
(72,'Roxas City','Capiz','V',11.585,122.751,'City',3500,2,'fd,sw',0,11,5,'Capiz seafood hub and gateway to Sicogon and Gigantes.','Fly to Roxas City, or ride from Iloilo, about 3 hrs.','Try fresh seafood and visit Sunburst Park.','R6','Region VI · Western Visayas',0,0),
(73,'Sicogon Island','Iloilo','V',11.490,123.250,'Beach',7000,3,'sw,rl',0,3,6,'Quiet beach island off northeast Iloilo.','Ferry from Roxas City or Estancia to Sicogon.','Resort transfers are usually arranged in advance.','R6','Region VI · Western Visayas',0,0),
(74,'Concepcion Islands','Iloilo','V',11.217,123.117,'Island',5000,2,'ih,fd',0,3,6,'Cluster of small islands with seafood and sandbars.','Bus to Concepcion, Iloilo, then a boat.','Book boats in advance, and enjoy the fresh seafood.','R6','Region VI · Western Visayas',1,0),
(75,'Gigantes Islands','Iloilo','V',11.600,123.350,'Island',6500,3,'ih,sw,fd',0,3,6,'Sandbars, scallops, and caves off Carles, Iloilo.','Van from Iloilo City to Carles, then a boat, about 4 to 5 hrs total.','Bring cash, since there are few ATMs.','R6','Region VI · Western Visayas',1,0),
