-- Destinify database (675 destinations). Generated by tools/build_sql.py from assets/data.js. Do not edit by hand.
-- Upgrade for an existing database. Safe to run more than once. Keeps users, reviews, favorites and trips.
-- Adds the missing columns and tables, then adds or refreshes every destination (hidden flags are kept).
-- Run it on a database created from the previous database/destinify.sql (destination ids 1 to 300 unchanged).
USE destinify_app;
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS regions (
  code VARCHAR(10) PRIMARY KEY,
  name VARCHAR(80) NOT NULL,
  short VARCHAR(20) NOT NULL
) ENGINE=InnoDB;
ALTER TABLE destinations
  ADD COLUMN IF NOT EXISTS region_code VARCHAR(10) NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS region_name VARCHAR(80) NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS tiktok TINYINT(1) NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS user_profiles (
  user_id INT UNSIGNED NOT NULL PRIMARY KEY,
  full_name VARCHAR(100) NOT NULL DEFAULT '',
  email VARCHAR(150) NOT NULL DEFAULT '',
  phone VARCHAR(30) NOT NULL DEFAULT '',
  home_city VARCHAR(80) NOT NULL DEFAULT '',
  bio VARCHAR(200) NOT NULL DEFAULT '',
  budget INT UNSIGNED NOT NULL DEFAULT 8000,
  fav_types VARCHAR(300) NOT NULL DEFAULT '',
  avatar MEDIUMTEXT NULL,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_profile_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_log (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id INT UNSIGNED NULL,
  message VARCHAR(255) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ON DUPLICATE KEY UPDATE name=VALUES(name), short=VALUES(short);

ON DUPLICATE KEY UPDATE name=VALUES(name),province=VALUES(province),region_group=VALUES(region_group),lat=VALUES(lat),lng=VALUES(lng),type=VALUES(type),budget_php=VALUES(budget_php),days=VALUES(days),activities=VALUES(activities),popular=VALUES(popular),best_start=VALUES(best_start),best_end=VALUES(best_end),description=VALUES(description),getting_there=VALUES(getting_there),tip=VALUES(tip),region_code=VALUES(region_code),region_name=VALUES(region_name),tiktok=VALUES(tiktok);

